N = int(input())
A = list(map(int, input().split()))
M = 1000000007
memo = {}

def count(arr, i, j):
	try:
		return memo[i, j]
	except:
		pass
	n = j - i
	if n == 1:
		memo[i, j] = 1
		return 1
	if arr[i] < max((arr[k] for k in range(i, j))):
		memo[i, j] = 0
		return 0
	memo[i, j] = out = sum((count(arr, i + 1, i + 2 + 2 * k) * count(arr, i + 2 + 2 * k, j) for k in range((n - 1) // 2))) % M
	return out
print(count(A, 0, N))
